using System.Text.Json;
using System.Text;
using System.Text.RegularExpressions;

// One emitted namespace module. Path is relative to the entry module's directory.
internal sealed record EmittedFile(string Path, string Source);

internal sealed class TypeScriptEmitter
{
	public const string Header = "// Generated by game-data. Edit the catalog/compiler, not this file.";
	private readonly CompilationContract contract;
	private readonly Dictionary<string, string> names = new(StringComparer.Ordinal);
	// Each object goes in the module of its CLR namespace, so no generated file
	// holds the whole contract. While a module is being written, references to
	// objects in other modules are recorded here so its import list can be built
	// after its body.
	private readonly Dictionary<string, string> modules = new(StringComparer.Ordinal);
	private string currentModule = "";
	private readonly SortedSet<(string Module, string Name)> typeImports = new();
	private readonly SortedSet<(string Module, string Name)> valueImports = new();
	// Only enum codecs need Effect's Schema; a module imports it only when used.
	private bool usesEffectSchema;
	public TypeScriptEmitter(CompilationContract contract)
	{
		this.contract = contract;
		var used = new HashSet<string> { "Xml", "Schema", "Value", "ValueSchema", "XmlSchema" };
		foreach (var item in contract.Objects)
		{
			// Full CLR names stay understandable and deterministic across collisions.
			// Reserve each declaration family together, including payload/schema names.
			var stem = "T_" + Regex.Replace(item.Id, "[^A-Za-z0-9_$]", "_");
			var name = stem;
			for (var index = 2; new[] { "", "Payload", "Schema", "PayloadSchema" }.Any(s => used.Contains(name + s)); index++) name = stem + index;
			foreach (var suffix in new[] { "", "Payload", "Schema", "PayloadSchema" }) used.Add(name + suffix);
			names.Add(item.Id, name);
			modules.Add(item.Id, ModuleOf(item.Id));
		}
	}
	// The CLR namespace of a type ID, used as its module name. Generic arguments are
	// dropped first, so SaveablePair`2[System.Int32,...] belongs to its definition's
	// namespace (StardewValley.Util), not to the namespace of an argument.
	private static string ModuleOf(string id)
	{
		var end = id.IndexOfAny(['`', '[']);
		var definition = end < 0 ? id : id[..end];
		var dot = definition.LastIndexOf('.');
		var ns = dot < 0 ? "global" : definition[..dot];
		return Regex.Replace(ns, "[^A-Za-z0-9_.-]", "_");
	}
	private static string Q(string value) => JsonSerializer.Serialize(value, Cli.Json);
	private string Name(string id) => names[id];
	// A reference from the object being written to a declaration of another object.
	// Type-only suffixes ("" and "Payload") become `import type`; schema constants
	// are values. References inside the current module need no import.
	private string Ref(string id, string suffix)
	{
		if (modules[id] != currentModule)
			(suffix is "" or "Payload" ? typeImports : valueImports).Add((modules[id], Name(id) + suffix));
		return Name(id) + suffix;
	}
	// Save-facing property names keep domain code independent of CLR backing-field
	// names (for example modDataForSerialization). Attributes retain member names
	// so an attribute and an element with the same XML name remain distinct fields.
	private static string Property(FieldContract field) => field.Placement == "attribute" ? field.MemberName : field.XmlName;
	private string Type(ValueContract value) => value.Kind switch
	{
		"scalar" => value.Type switch
		{
			"System.String" or "System.Guid" => "string",
			"System.Boolean" => "boolean",
			"System.Int64" or "System.UInt64" => "bigint",
			_ => "number"
		},
		"enum" => string.Join(" | ", value.Labels!.Select(Q)) + (value.NullableText ? " | null" : ""),
		"object" => Ref(value.Type!, ""),
		"nullable" => $"({Type(value.Value!)}) | null",
		"array" => $"Array<{Type(value.Item!)}>",
		"inventory" => $"Array<({Type(value.Item!)}) | null>",
		"dictionary" => $"Array<{{ key: {Type(value.Key!)}; value: {Type(value.Value!)}; [extra: string]: unknown }}>",
		_ => throw new InvalidDataException("Unknown value contract " + value.Kind)
	};
	private string Codec(ValueContract value) => value.Kind switch
	{
		"scalar" => $"Xml.scalar({Q(value.Type!)})",
		"enum" => value.NullableText ? $"Xml.text(Xml.nullableEnumText([{string.Join(", ", value.Labels!.Select(Q))}]))" : EnumLiterals(value.Labels!),
		"object" => $"Xml.lazy(() => {Ref(value.Type!, "Schema")})",
		"nullable" => $"Xml.nullable({Codec(value.Value!)})",
		"array" => $"Xml.wrapped({Codec(value.Item!)}, {Q(value.ItemName!)})",
		"inventory" => $"Xml.wrapped(Xml.nullable({Codec(value.Item!)}), \"Item\")",
		"dictionary" => $"Xml.dictionary({Codec(value.Key!)}, {Q(value.KeyName!)}, {Codec(value.Value!)}, {Q(value.ValueName!)}{(value.KeyIdentity is null ? "" : ", " + Q(value.KeyIdentity))})",
		_ => throw new InvalidDataException("Unknown value contract " + value.Kind)
	};
	private string EnumLiterals(List<string> labels)
	{
		usesEffectSchema = true;
		return $"Xml.text(Schema.Literals([{string.Join(", ", labels.Select(Q))}]))";
	}
	private string FieldCodec(FieldContract field)
	{
		var codec = Codec(field.Value);
		// NetField exposes one logical value through its XML enumerable contract.
		// The editor works with that value, not a one-element implementation list.
		if (field.MaxItems == 1)
			return field.Placement == "collection" ? $"Xml.single({codec}, {Q(field.ItemName!)})" : field.Value.Kind == "object" ? $"Xml.optionalReference({codec})" : codec;
		return field.Placement switch
		{
			"repeated" => $"Xml.sequence({codec}, {field.MaxItems?.ToString() ?? "undefined"})",
			"collection" => $"Xml.wrapped({codec}, {Q(field.ItemName!)}, {field.MaxItems?.ToString() ?? "undefined"})",
			_ => codec
		};
	}
	// Writes one object's payload type, public type, payload schema and dispatch
	// schema. Every declaration is exported, because other namespaces' modules
	// import them; the entry module re-exports only the public types.
	private void AppendObject(StringBuilder output, ObjectContract obj)
	{
		var name = Name(obj.Id);
		output.AppendLine($"export type {name}Payload = {{");
		// Literals may omit optional XML members, including empty repeated fields.
		// Decoding initializes repeated fields; creation need not spell out every list.
		foreach (var field in obj.Fields)
			output.AppendLine($"\t{Q(Property(field))}?: {(field.Multiple && field.MaxItems != 1 ? $"Array<{Type(field.Value)}>" : Type(field.Value))}{(field.MaxItems == 1 && (field.Placement == "collection" || field.Value.Kind == "object") ? " | null" : "")};");
		output.AppendLine("\t[extra: string]: unknown;\n};");
		var variants = obj.Variants.Select(id => $"({Ref(id, "Payload")} & {{ readonly $type: {Q(id)} }})").ToList();
		var simple = obj.Variants.Count == 1 && obj.Variants[0] == obj.Id;
		// A concrete field (such as Farmer.boots) still carries item identity in
		// the editor, just like the same instance in an Item inventory slot.
		var exposeType = contract.Objects.Any(parent => parent.Id != "System.Object" && parent.Variants.Count > 1 && parent.Variants.Contains(obj.Id));
		if (obj.Id == "System.Object") variants.Add("Xml.ScalarObject");
		if (!simple || obj.Id == "System.Object") variants.Add("Xml.UnknownObject");
		output.AppendLine($"export type {name} = {(simple && obj.Id != "System.Object" ? name + "Payload" + (exposeType ? $" & {{ readonly $type?: {Q(obj.Id)} }}" : "") : string.Join(" | ", variants))};\n");
		output.AppendLine($"export const {name}PayloadSchema = Xml.object({{");
		foreach (var field in obj.Fields)
			output.AppendLine($"\t[{Q(Property(field))}]: {{ xmlName: {Q((field.Placement == "attribute" ? "@_" : "") + field.XmlName)}, codec: {FieldCodec(field)}{(field.Repeated && field.MaxItems != 1 ? ", repeated: true, optional: true" : ", optional: true")} }},");
		output.AppendLine("});");
		var cases = obj.Variants.Select(id =>
		{
			var variant = contract.Objects.Single(o => o.Id == id);
			return $"{{ id: {Q(id)}, name: {Q(variant.TypeName)}, namespace: {Q(variant.TypeNamespace)}, codec: {Ref(id, "PayloadSchema")} }}";
		});
		// Every reference is deferred, including dispatch construction. Recursion
		// and inheritance therefore need no source factoring or initialization order,
		// and modules may import each other in cycles: no module reads another
		// module's binding while it is being evaluated.
		output.AppendLine($"export const {name}Schema: Xml.Codec<{name}> = Xml.lazy(() => Xml.polymorphic({Q(obj.Id)}, [{string.Join(", ", cases)}]{(exposeType ? ", true" : "")})) as Xml.Codec<{name}>;\n");
	}
	// The entry module's document-level exports: the root value and XML schemas,
	// the decoded value type and the reviewed type-ID constructors.
	private void AppendRootExports(StringBuilder output)
	{
		output.AppendLine($"export const ValueSchema = {Name(contract.Root.Id)}Schema;");
		output.AppendLine($"export const XmlSchema = Xml.document({Q(contract.Root.RootName)}, ValueSchema);");
		output.AppendLine("export type Value = typeof ValueSchema.Type;");
		// Constructors select a reviewed runtime type without embedding CLR namespace
		// guesses throughout editor operations. Ambiguous XML names are not exported.
		var ids = contract.Objects.Where(o => o.TypeNamespace.Length == 0)
			.GroupBy(o => o.TypeName).Where(group => group.Count() == 1)
			.ToDictionary(group => group.Key, group => group.Single().Id);
		output.AppendLine($"export const TypeIds = {JsonSerializer.Serialize(ids, Cli.Json)} as const;");
	}
	// Emits the codec as one module per CLR namespace in `directory`, plus an entry
	// module that re-exports the public types and builds the document schema.
	// Importers use only the entry module. `chunkRuntimeImport` is the runtime path
	// as seen from inside `directory`.
	public (string Entry, List<EmittedFile> Modules) Emit(string directory, string runtimeImport, string chunkRuntimeImport)
	{
		// Module files that differ only by case on case-insensitive filesystems would
		// overwrite each other, so refuse such a contract instead of losing types.
		var collision = modules.Values.Distinct(StringComparer.Ordinal)
			.GroupBy(module => module, StringComparer.OrdinalIgnoreCase).FirstOrDefault(group => group.Count() > 1);
		if (collision is not null)
			throw new InvalidDataException($"Namespaces {string.Join(", ", collision)} would share one module file.");
		var files = new List<EmittedFile>();
		var publicTypes = new List<(string Module, string Name)>();
		// Modules follow the contract's order of first appearance, and objects keep
		// their contract order within a module, so output is deterministic.
		foreach (var module in contract.Objects.Select(o => modules[o.Id]).Distinct(StringComparer.Ordinal))
		{
			currentModule = module;
			typeImports.Clear();
			valueImports.Clear();
			usesEffectSchema = false;
			var body = new StringBuilder();
			foreach (var obj in contract.Objects.Where(o => modules[o.Id] == module))
			{
				AppendObject(body, obj);
				publicTypes.Add((module, Name(obj.Id)));
			}
			// Imports are known only after the body has recorded its references.
			var output = new StringBuilder(Header + "\n");
			output.AppendLine($"// CLR namespace {module}. The entry module re-exports its public types.");
			if (usesEffectSchema) output.AppendLine("import { Schema } from \"effect\";");
			output.AppendLine($"import * as Xml from {Q(chunkRuntimeImport)};");
			foreach (var group in typeImports.GroupBy(item => item.Module))
				output.AppendLine($"import type {{ {string.Join(", ", group.Select(item => item.Name))} }} from {Q($"./{group.Key}.ts")};");
			foreach (var group in valueImports.GroupBy(item => item.Module))
				output.AppendLine($"import {{ {string.Join(", ", group.Select(item => item.Name))} }} from {Q($"./{group.Key}.ts")};");
			output.AppendLine();
			output.Append(body);
			files.Add(new($"{directory}/{module}.ts", output.ToString()));
		}
		currentModule = "";
		// The entry module imports only the root schema as a value. Every other module
		// is reached through that schema's imports, and type re-exports are erased.
		var entry = new StringBuilder(Header + "\n");
		entry.AppendLine($"// The codec is split into one module per CLR namespace under ./{directory}/.");
		entry.AppendLine("// This entry module re-exports their public types and builds the document schema.");
		entry.AppendLine($"import * as Xml from {Q(runtimeImport)};");
		entry.AppendLine($"import {{ {Name(contract.Root.Id)}Schema }} from {Q($"./{directory}/{modules[contract.Root.Id]}.ts")};\n");
		foreach (var group in publicTypes.GroupBy(item => item.Module))
			entry.AppendLine($"export type {{ {string.Join(", ", group.Select(item => item.Name))} }} from {Q($"./{directory}/{group.Key}.ts")};");
		entry.AppendLine();
		AppendRootExports(entry);
		return (entry.ToString(), files);
	}
}
